<style>
@font-face {
  font-family: 'Kalpurush';
  src: url('https://cdn.jsdelivr.net/gh/maateen/kalpurush-fonts@master/kalpurush.woff2') format('woff2'),
       url('https://cdn.jsdelivr.net/gh/maateen/kalpurush-fonts@master/kalpurush.woff') format('woff'),
       url('https://cdn.jsdelivr.net/gh/maateen/kalpurush-fonts@master/kalpurush.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* ======== CONFIG ======== */
:root {
  --brand-deep: #0D47A1;
  --brand-blue: #1565C0;
  --brand-blue-light: #E3F0FB;
  --brand-orange: #F57C00;
  --brand-orange-hover: #E65100;
  --brand-orange-glow: rgba(245,124,0,0.22);
  --brand-green: #2E7D32;
  --brand-green-light: #E8F5E9;
  --brand-red: #C62828;
  --bg: #F5F8FC;
  --bg-alt: #EDF2F7;
  --surface: #FFFFFF;
  --surface-raised: #FFFFFF;
  --ink: #0F1E30;
  --ink-2: #4E6175;
  --ink-3: #8090A2;
  --border: #D6E2ED;
  --border-focus: #42A5F5;
  --radius: 10px;
  --radius-lg: 16px;
  --radius-pill: 50px;
  --shadow: 0 2px 8px rgba(15,30,48,0.06);
  --shadow-lg: 0 8px 28px rgba(15,30,48,0.10);
  --shadow-cta: 0 4px 16px rgba(245,124,0,0.30);
  --font: 'Kalpurush', sans-serif;
}

/* ======== RESET ======== */
*,*::before,*::after { margin:0; padding:0; box-sizing:border-box; }
html { scroll-behavior: smooth; -webkit-tap-highlight-color: transparent; }
body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { max-width:100%; height:auto; display:block; }
a { text-decoration:none; color:inherit; }

/* ======== UTILITY ======== */
.container { max-width: 480px; margin: 0 auto; padding: 0 16px; }
.section { padding: 40px 0; }
.section-alt { background: var(--bg-alt); }
.text-center { text-align: center; }
.badge {
  display: inline-block; padding: 4px 14px; border-radius: var(--radius-pill);
  font-size: 13px; font-weight: 600; letter-spacing: 0.02em;
}
.badge-orange { background: var(--brand-orange); color: #fff; }
.badge-green { background: var(--brand-green); color: #fff; }
.badge-blue { background: var(--brand-blue); color: #fff; }

/* ======== HEADER ======== */
.header {
  background: var(--surface);
  padding: 10px 0;
  border-bottom: 2px solid var(--brand-blue);
  position: sticky; top: 0; z-index: 100;
}
.header .container {
  display: flex; align-items: center; justify-content: space-between;
}
.header-logo { height: 38px; width: auto; }
.header-cta {
  background: var(--brand-orange); color: #fff;
  padding: 8px 20px; border-radius: var(--radius-pill);
  font-weight: 600; font-size: 14px;
  box-shadow: var(--shadow-cta);
  transition: background 0.2s;
}
.header-cta:hover { background: var(--brand-orange-hover); }

/* ======== HERO ======== */
.hero {
  background: linear-gradient(135deg, var(--brand-deep) 0%, var(--brand-blue) 100%);
  color: #fff; padding: 32px 0 36px; text-align: center;
}
.hero-badge {
  display: inline-block; background: var(--brand-orange); color: #fff;
  padding: 5px 18px; border-radius: var(--radius-pill);
  font-size: 13px; font-weight: 700; margin-bottom: 14px;
  letter-spacing: 0.03em;
}
.hero h1 {
  font-size: 26px; font-weight: 700; line-height: 1.35;
  margin-bottom: 10px; text-wrap: balance;
}
.hero h1 span { color: #FFD54F; }
.hero-sub { font-size: 16px; opacity: 0.92; margin-bottom: 20px; }
.hero-img {
  width: 280px; height: 280px; object-fit: contain;
  margin: 0 auto 20px; filter: drop-shadow(0 8px 24px rgba(0,0,0,0.25));
}
.hero-price-row {
  display: flex; gap: 8px; justify-content: center; flex-wrap: wrap;
  margin-bottom: 18px;
}
.hero-price-chip {
  background: rgba(255,255,255,0.15); backdrop-filter: blur(6px);
  padding: 6px 16px; border-radius: var(--radius-pill);
  font-size: 14px; font-weight: 600;
}
.hero-price-chip.highlight {
  background: var(--brand-orange); font-size: 15px;
}
.hero-cta {
  display: inline-block; background: var(--brand-orange); color: #fff;
  padding: 14px 36px; border-radius: var(--radius-pill);
  font-size: 18px; font-weight: 700;
  box-shadow: var(--shadow-cta);
  transition: transform 0.15s, background 0.2s;
}
.hero-cta:hover { background: var(--brand-orange-hover); transform: scale(1.03); }

/* ======== SAVINGS BAR ======== */
.savings-bar {
  background: var(--brand-green-light); padding: 16px 0;
  text-align: center; border-bottom: 1px solid #C8E6C9;
}
.savings-bar p { font-size: 15px; font-weight: 600; color: var(--brand-green); }
.savings-bar span { font-size: 20px; font-weight: 700; }

/* ======== PROBLEM ======== */
.problem-list { list-style: none; }
.problem-list li {
  display: flex; gap: 12px; align-items: flex-start;
  padding: 12px 0; border-bottom: 1px solid var(--border);
}
.problem-list li:last-child { border: none; }
.problem-icon { font-size: 22px; flex-shrink: 0; margin-top: 2px; }
.problem-text { font-size: 15px; color: var(--ink-2); }
.problem-text strong { color: var(--ink); }

/* ======== BENEFITS ======== */
.benefits-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 12px;
}
.benefit-card {
  background: var(--surface); border-radius: var(--radius);
  padding: 18px 14px; text-align: center;
  box-shadow: var(--shadow); border: 1px solid var(--border);
}
.benefit-icon { font-size: 28px; margin-bottom: 8px; }
.benefit-title { font-size: 14px; font-weight: 700; margin-bottom: 4px; }
.benefit-desc { font-size: 13px; color: var(--ink-2); }

/* ======== SHOWCASE ======== */
.showcase-main {
  border-radius: var(--radius-lg); overflow: hidden;
  box-shadow: var(--shadow-lg); margin-bottom: 16px;
  background: var(--surface);
}
.showcase-main img { width: 100%; }
.showcase-thumbs {
  display: grid; grid-template-columns: 1fr 1fr; gap: 10px;
}
.showcase-thumb {
  border-radius: var(--radius); overflow: hidden;
  box-shadow: var(--shadow); background: var(--surface);
}
.showcase-thumb img { width: 100%; }

/* ======== PRICING CARDS ======== */
.pricing-cards { display: flex; flex-direction: column; gap: 14px; }
.price-card {
  background: var(--surface); border-radius: var(--radius-lg);
  padding: 22px 18px; box-shadow: var(--shadow);
  border: 2px solid var(--border); position: relative;
  cursor: pointer; transition: border-color 0.2s, box-shadow 0.2s;
}
.price-card:hover { border-color: var(--brand-blue); }
.price-card.selected {
  border-color: var(--brand-orange);
  box-shadow: 0 0 0 3px var(--brand-orange-glow), var(--shadow-lg);
}
.price-card.featured {
  border-color: var(--brand-orange);
  background: linear-gradient(to bottom, #FFF8F0, var(--surface));
}
.price-card-badge {
  position: absolute; top: -12px; left: 50%; transform: translateX(-50%);
  background: var(--brand-orange); color: #fff;
  padding: 3px 16px; border-radius: var(--radius-pill);
  font-size: 12px; font-weight: 700; white-space: nowrap;
}
.price-card-best .price-card-badge {
  background: var(--brand-green);
}
.price-card-row {
  display: flex; align-items: center; justify-content: space-between;
}
.price-card-qty {
  font-size: 15px; font-weight: 600;
}
.price-card-qty span { font-size: 22px; font-weight: 700; color: var(--brand-blue); }
.price-card-amount {
  text-align: right;
}
.price-card-total {
  font-size: 24px; font-weight: 700; color: var(--brand-orange);
}
.price-card-original {
  font-size: 13px; color: var(--ink-3); text-decoration: line-through;
}
.price-card-per-unit {
  font-size: 13px; color: var(--ink-2); margin-top: 2px;
}
.price-card-save {
  display: inline-block; margin-top: 8px;
  background: var(--brand-green-light); color: var(--brand-green);
  padding: 4px 12px; border-radius: var(--radius-pill);
  font-size: 13px; font-weight: 600;
}
.price-card-radio {
  width: 22px; height: 22px; border-radius: 50%;
  border: 2px solid var(--border); flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  transition: border-color 0.2s;
}
.price-card.selected .price-card-radio {
  border-color: var(--brand-orange);
}
.price-card.selected .price-card-radio::after {
  content: ''; width: 12px; height: 12px; border-radius: 50%;
  background: var(--brand-orange);
}

/* ======== USE CASES ======== */
.usecase-list { display: flex; flex-direction: column; gap: 10px; }
.usecase-item {
  display: flex; align-items: center; gap: 14px;
  background: var(--surface); padding: 14px 16px;
  border-radius: var(--radius); box-shadow: var(--shadow);
  border-left: 4px solid var(--brand-blue);
}
.usecase-icon { font-size: 26px; flex-shrink: 0; }
.usecase-text { font-size: 15px; font-weight: 500; }

/* ======== COLOR SELECTION ======== */
.color-options { display: flex; gap: 14px; justify-content: center; }
.color-btn {
  width: 52px; height: 52px; border-radius: 50%;
  border: 3px solid var(--border); cursor: pointer;
  transition: border-color 0.2s, box-shadow 0.2s;
  position: relative;
}
.color-btn.active {
  border-color: var(--brand-orange);
  box-shadow: 0 0 0 3px var(--brand-orange-glow);
}
.color-btn[data-color="white"] { background: #F5F5F5; }
.color-btn[data-color="mint"] { background: #A5D6A7; }
.color-btn[data-color="black"] { background: #37474F; }
.color-label {
  display: block; text-align: center; font-size: 13px;
  font-weight: 600; margin-top: 6px; color: var(--ink-2);
}

/* ======== TRUST ======== */
.trust-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; }
.trust-item {
  text-align: center; background: var(--surface);
  padding: 16px 8px; border-radius: var(--radius);
  box-shadow: var(--shadow);
}
.trust-icon { font-size: 28px; margin-bottom: 6px; }
.trust-label { font-size: 12px; font-weight: 600; color: var(--ink-2); }

/* ======== SPECS ======== */
.specs-table {
  width: 100%; border-collapse: collapse;
  background: var(--surface); border-radius: var(--radius);
  overflow: hidden; box-shadow: var(--shadow);
}
.specs-table tr { border-bottom: 1px solid var(--border); }
.specs-table tr:last-child { border: none; }
.specs-table td {
  padding: 12px 14px; font-size: 14px;
}
.specs-table td:first-child {
  font-weight: 600; color: var(--ink-2); width: 40%;
  background: var(--bg-alt);
}

/* ======== FAQ ======== */
.faq-item {
  background: var(--surface); border-radius: var(--radius);
  margin-bottom: 10px; box-shadow: var(--shadow); overflow: hidden;
}
.faq-q {
  padding: 14px 16px; font-size: 15px; font-weight: 600;
  cursor: pointer; display: flex; justify-content: space-between;
  align-items: center; user-select: none;
}
.faq-q::after { content: '+'; font-size: 20px; color: var(--ink-3); transition: transform 0.2s; }
.faq-item.open .faq-q::after { content: '−'; }
.faq-a {
  padding: 0 16px; max-height: 0; overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  font-size: 14px; color: var(--ink-2); line-height: 1.7;
}
.faq-item.open .faq-a { max-height: 300px; padding: 0 16px 16px; }

/* ======== ORDER FORM ======== */
.order-section {
  background: linear-gradient(180deg, var(--brand-blue) 0%, var(--brand-deep) 100%);
  padding: 40px 0; color: #fff;
}
.order-form {
  background: var(--surface); color: var(--ink);
  border-radius: var(--radius-lg); padding: 24px 18px;
  box-shadow: var(--shadow-lg);
}
.order-title {
  font-size: 20px; font-weight: 700; text-align: center;
  margin-bottom: 20px; color: var(--ink);
}
.form-group { margin-bottom: 16px; }
.form-label {
  display: block; font-size: 14px; font-weight: 600;
  margin-bottom: 6px; color: var(--ink-2);
}
.form-input, .form-select {
  width: 100%; padding: 12px 14px; border: 1.5px solid var(--border);
  border-radius: var(--radius); font-size: 15px;
  font-family: var(--font); background: var(--surface);
  color: var(--ink); transition: border-color 0.2s;
  -webkit-appearance: none;
}
.form-input:focus, .form-select:focus {
  outline: none; border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(66,165,245,0.15);
}
.form-input.error { border-color: var(--brand-red); }
.form-error {
  font-size: 12px; color: var(--brand-red); margin-top: 4px; display: none;
}
.form-input.error + .form-error { display: block; }
textarea.form-input { resize: vertical; min-height: 70px; }

/* Order Summary */
.order-summary {
  background: var(--bg-alt); border-radius: var(--radius);
  padding: 16px; margin: 20px 0;
}
.summary-row {
  display: flex; justify-content: space-between;
  padding: 6px 0; font-size: 14px;
}
.summary-row.total {
  border-top: 2px solid var(--border); margin-top: 8px;
  padding-top: 12px; font-size: 18px; font-weight: 700;
  color: var(--brand-orange);
}
.summary-save {
  text-align: center; margin-top: 8px; padding: 6px;
  background: var(--brand-green-light); border-radius: var(--radius-pill);
  color: var(--brand-green); font-size: 13px; font-weight: 600;
}

/* Submit */
.order-submit {
  width: 100%; padding: 16px; border: none;
  background: var(--brand-orange); color: #fff;
  font-size: 18px; font-weight: 700; border-radius: var(--radius-pill);
  cursor: pointer; font-family: var(--font);
  box-shadow: var(--shadow-cta);
  transition: background 0.2s, transform 0.15s;
}
.order-submit:hover { background: var(--brand-orange-hover); }
.order-submit:active { transform: scale(0.98); }
.order-submit:disabled { opacity: 0.6; cursor: not-allowed; }
.cod-note {
  text-align: center; margin-top: 12px; font-size: 13px; color: var(--ink-3);
}

/* Order Color Select in Form */
.form-color-options { display: flex; gap: 10px; }
.form-color-btn {
  flex: 1; padding: 10px; border: 2px solid var(--border);
  border-radius: var(--radius); text-align: center;
  cursor: pointer; font-size: 13px; font-weight: 600;
  background: var(--surface); transition: border-color 0.2s;
}
.form-color-btn.active {
  border-color: var(--brand-orange);
  background: #FFF3E0;
}
.form-color-dot {
  width: 20px; height: 20px; border-radius: 50%;
  margin: 0 auto 4px; border: 1px solid #ddd;
}

/* Shipping Options in Form */
.form-shipping-options { display: flex; gap: 10px; margin-top: 4px; }
.form-shipping-btn {
  flex: 1; padding: 12px 10px; border: 2px solid var(--border);
  border-radius: var(--radius); text-align: center;
  cursor: pointer; background: var(--surface);
  transition: all 0.2s ease; position: relative;
}
.form-shipping-btn:hover { border-color: var(--brand-blue); }
.form-shipping-btn.active {
  border-color: var(--brand-orange);
  background: #FFF3E0;
  box-shadow: 0 0 0 2px var(--brand-orange-glow);
}
.form-shipping-title { font-size: 14px; font-weight: 700; color: var(--ink); margin-bottom: 2px; }
.form-shipping-charge { font-size: 13px; font-weight: 600; color: var(--brand-orange); }

/* Form Package Options */
.form-pkg-options { display: flex; flex-direction: column; gap: 8px; margin-bottom: 8px; }
.form-pkg-btn {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 14px; border: 2px solid var(--border);
  border-radius: var(--radius); cursor: pointer;
  background: var(--surface); transition: all 0.2s ease;
}
.form-pkg-btn:hover { border-color: var(--brand-blue); }
.form-pkg-btn.active {
  border-color: var(--brand-orange);
  background: #FFF8F0;
  box-shadow: 0 0 0 2px var(--brand-orange-glow);
}
.form-pkg-left { display: flex; align-items: center; gap: 10px; }
.form-pkg-radio {
  width: 18px; height: 18px; border-radius: 50%;
  border: 2px solid var(--border); flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
}
.form-pkg-btn.active .form-pkg-radio { border-color: var(--brand-orange); }
.form-pkg-btn.active .form-pkg-radio::after {
  content: ''; width: 10px; height: 10px; border-radius: 50%;
  background: var(--brand-orange);
}
.form-pkg-name { font-size: 14px; font-weight: 700; color: var(--ink); }
.form-pkg-badge {
  display: inline-block; font-size: 11px; font-weight: 700;
  background: var(--brand-green-light); color: var(--brand-green);
  padding: 2px 8px; border-radius: var(--radius-pill); margin-left: 6px;
}
.form-pkg-price { font-size: 15px; font-weight: 700; color: var(--brand-orange); }

/* Quantity Stepper */
.qty-stepper-wrap {
  display: flex; align-items: center; justify-content: space-between;
  background: var(--bg-alt); padding: 8px 12px; border-radius: var(--radius);
  margin-top: 6px;
}
.qty-stepper-label { font-size: 13px; font-weight: 600; color: var(--ink-2); }
.qty-stepper { display: flex; align-items: center; gap: 8px; }
.qty-btn {
  width: 32px; height: 32px; border-radius: 6px; border: 1px solid var(--border);
  background: var(--surface); font-size: 18px; font-weight: 700;
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  color: var(--ink); user-select: none; transition: background 0.15s;
}
.qty-btn:hover { background: #E3F2FD; }
.qty-display { font-size: 16px; font-weight: 700; min-width: 24px; text-align: center; }

/* ======== FOOTER ======== */
.footer {
  background: var(--brand-deep); color: rgba(255,255,255,0.7);
  padding: 30px 0; text-align: center; font-size: 13px;
}
.footer-logo { height: 40px; margin: 0 auto 10px; }

/* ======== STICKY BAR ======== */
.sticky-bar {
  position: fixed; bottom: 0; left: 0; right: 0;
  background: var(--surface); padding: 10px 16px;
  box-shadow: 0 -2px 12px rgba(0,0,0,0.1);
  z-index: 200; display: none;
  border-top: 2px solid var(--brand-orange);
}
.sticky-bar.visible { display: block; }
.sticky-inner {
  max-width: 480px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
}
.sticky-info { font-size: 13px; }
.sticky-info .qty { font-weight: 700; color: var(--brand-blue); }
.sticky-info .price { font-size: 17px; font-weight: 700; color: var(--brand-orange); }
.sticky-btn {
  background: var(--brand-orange); color: #fff;
  padding: 10px 24px; border-radius: var(--radius-pill);
  font-weight: 700; font-size: 15px;
  box-shadow: var(--shadow-cta);
  white-space: nowrap; flex-shrink: 0;
}

/* ======== SECTION TITLES ======== */
.section-title {
  font-size: 22px; font-weight: 700; text-align: center;
  margin-bottom: 8px; text-wrap: balance;
}
.section-sub {
  font-size: 15px; color: var(--ink-2); text-align: center;
  margin-bottom: 24px;
}

/* ======== SUCCESS STATE ======== */
.order-success {
  display: none;
  background: #ffffff;
  border: 2px solid #22c55e;
  border-radius: 20px;
  padding: 32px 20px;
  box-shadow: 0 16px 40px rgba(34, 197, 94, 0.12), 0 4px 16px rgba(0, 0, 0, 0.04);
  text-align: center;
  animation: successFadeIn 0.4s ease-out forwards;
}
@keyframes successFadeIn {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
.order-success.show { display: block; }
.success-badge {
  width: 76px;
  height: 76px;
  background: #ecfdf5;
  border: 3px solid #22c55e;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  box-shadow: 0 6px 20px rgba(34, 197, 94, 0.25);
  animation: badgePop 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}
@keyframes badgePop {
  0% { transform: scale(0.6); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}
.success-badge svg {
  width: 42px;
  height: 42px;
  stroke: #16a34a;
}
.success-title {
  font-size: 24px;
  font-weight: 800;
  color: #14532d;
  margin-bottom: 8px;
