}
.success-cust-greeting {
  font-size: 16px;
  color: #1e293b;
  line-height: 1.6;
  margin-bottom: 20px;
  font-weight: 500;
}
.success-cust-greeting strong {
  color: #0f172a;
  font-weight: 800;
}
.success-receipt {
  background: #f8fafc;
  border: 1.5px solid #e2e8f0;
  border-radius: 14px;
  padding: 16px 18px;
  margin: 0 0 20px;
  text-align: left;
}
.receipt-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px dashed #cbd5e1;
  font-size: 15px;
}
.receipt-row:last-child {
  border-bottom: none;
  padding-bottom: 2px;
}
.receipt-row.total-row {
  border-top: 2px solid #e2e8f0;
  border-bottom: none;
  padding-top: 14px;
  margin-top: 6px;
}
.receipt-label {
  color: #475569;
  font-weight: 600;
  font-size: 14.5px;
}
.receipt-value {
  color: #0f172a;
  font-weight: 700;
  font-size: 15px;
  text-align: right;
}
.invoice-badge-val {
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
  font-weight: 800;
  font-size: 15px;
  padding: 3px 10px;
  border-radius: 6px;
  display: inline-block;
  letter-spacing: 0.5px;
}
.total-label-highlight {
  color: #0f172a;
  font-size: 17px;
  font-weight: 800;
}
.total-val-highlight {
  color: #ea580c;
  font-size: 24px;
  font-weight: 900;
}
.success-notice-box {
  background: #fffbeb;
  border: 1.5px solid #fde68a;
  border-radius: 12px;
  padding: 14px 16px;
  text-align: left;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 24px;
}
.notice-icon {
