  line-height: 1;
  flex-shrink: 0;
  margin-top: 2px;
}
.notice-text {
  color: #78350f;
  font-size: 14.5px;
  line-height: 1.6;
  font-weight: 600;
  margin: 0;
}
.success-cta-btn {
