        <div class="form-shipping-options">
          <div class="form-shipping-btn active" id="shipDhakaBtn" onclick="selectShippingType(1, {{ isset($shipping_inside->shipping_charge) ? (int)$shipping_inside->shipping_charge : 70 }})">
            <div class="form-shipping-title">ঢাকার ভিতরে</div>
