          <div class="form-shipping-btn" id="shipOutsideBtn" onclick="selectShippingType(2, {{ isset($shipping_outside->shipping_charge) ? (int)$shipping_outside->shipping_charge : 130 }})">
            <div class="form-shipping-title">ঢাকার বাইরে</div>
            <div class="form-shipping-charge">৳{{ $shipping_outside->shipping_charge ?? 130 }}</div>
