        <input type="tel" class="form-input" id="custPhone" placeholder="01XXXXXXXXX" maxlength="11" onfocus="triggerBeginCheckout()" required>
        <div class="form-error">সঠিক ১১ সংখ্যার মোবাইল নম্বর দিন</div>
      </div>

      <!-- Address -->
      <div class="form-group">
        <label class="form-label">সম্পূর্ণ ঠিকানা *</label>
        <textarea class="form-input" id="custAddress" placeholder="বাড়ি/হোল্ডিং নম্বর, রোড, এলাকা/থানা, জেলা" onfocus="triggerBeginCheckout()" required></textarea>
        <div class="form-error">ঠিকানা লিখুন</div>
      </div>

      <!-- Note -->
      <div class="form-group">
        <label class="form-label">বিশেষ নোট (ঐচ্ছিক)</label>
        <input type="text" class="form-input" id="custNote" placeholder="যেমন: ২টা সাদা + ১টা কালো চাই">
      </div>

      <!-- Order Summary -->
      <div class="order-summary">
        <div class="summary-row">
          <span id="summaryProduct">৩টা Turbo Fan</span>
          <span id="summarySubtotal">৳১,২৪৯</span>
        </div>
        <div class="summary-row">
          <span>ডেলিভারি চার্জ</span>
          <span id="summaryDelivery">৳{{ $shipping_inside->shipping_charge ?? 70 }}</span>
        </div>
        <div class="summary-row total">
