      <div class="success-cust-greeting">
        ধন্যবাদ <strong id="successCustName"></strong>, আপনার অর্ডারটি সফলভাবে গ্রহণ করা হয়েছে।
      </div>

      <!-- Structured Receipt -->
      <div class="success-receipt">
        <div class="receipt-row">
