          <span class="receipt-value"><span class="invoice-badge-val">#<span id="successInvoice"></span></span></span>
        </div>
        <div class="receipt-row">
          <span class="receipt-label">পেমেন্ট মেথড:</span>
          <span class="receipt-value" style="color:#16a34a; font-weight:700;">💵 ক্যাশ অন ডেলিভারি (COD)</span>
        </div>
        <div class="receipt-row total-row">
          <span class="total-label-highlight">সর্বমোট প্রদেয় বিল:</span>
          <span class="total-val-highlight" id="successGrandTotal"></span>
        </div>
      </div>

      <!-- Customer Care Notification -->
      <div class="success-notice-box">
        <span class="notice-icon">📞</span>
        <p class="notice-text">
          শীঘ্রই আমাদের কাস্টমার কেয়ার প্রতিনিধি আপনার সাথে ফোনে যোগাযোগ করে অর্ডারটি কনফার্ম করবেন এবং দ্রুত ডেলিভারি প্রক্রিয়া শুরু করবেন।
        </p>
