<footer class="footer">
  <div class="container">
    <img src="data:image/png;base64," alt="Mega Mart BD" class="footer-logo">
    <p>© 2024 Mega Mart BD. All rights reserved.</p>
   
  </div>
</footer>

<!-- ======== STICKY BAR ======== -->
<div class="sticky-bar" id="stickyBar">
  <div class="sticky-inner">
    <div class="sticky-info">
      <div class="qty" id="stickyQty">৩টা Turbo Fan</div>
      <div class="price" id="stickyPrice">৳১,২৪৯</div>
    </div>
    <a href="#order-form" class="sticky-btn">অর্ডার করুন</a>
  </div>
</div>

<script>
/* ========================================
   CONFIGURATION & STATE
   ======================================== */
var CONFIG = {
  productId: {{ $product->id ?? 206 }},
  productName: '{{ addslashes($product->name ?? "Turbo Portable Hand Fan") }}',
  productPrice: 649,
  productBrand: 'MegaMart',
  productCategory: 'Electronics / Portable Fans',
  prices: { 1: 649, 2: 1049, 3: 1249 },
  deliveryDhaka: {{ isset($shipping_inside->shipping_charge) ? (int)$shipping_inside->shipping_charge : 70 }},
  deliveryOutside: {{ isset($shipping_outside->shipping_charge) ? (int)$shipping_outside->shipping_charge : 130 }},
  orderApi: '{{ route("landing.turbo-fan-offer.store") }}',
  csrfToken: '{{ csrf_token() }}'
};

var state = {
  qty: 3,
  color: 'white',
  shippingType: 1, // 1: inside dhaka, 2: outside dhaka
  deliveryCharge: {{ isset($shipping_inside->shipping_charge) ? (int)$shipping_inside->shipping_charge : 70 }},
  viewItemFired: false,
  checkoutFired: false,
  isSubmitting: false,
  submitted: false,
  purchaseFired: false
};

/* Format number with commas */
function fmt(n) {
  return Number(n || 0).toLocaleString('en-US');
}

/* ========================================
   GOOGLE TAG MANAGER / DATALAYER TRACKING
   ======================================== */

// 1. View Item (Product View)
function triggerViewItem() {
  if (state.viewItemFired) return;
  state.viewItemFired = true;

  var unitPrice = parseFloat(Number(CONFIG.productPrice).toFixed(2));

  window.dataLayer = window.dataLayer || [];
  window.dataLayer.push({ ecommerce: null });
  window.dataLayer.push({
    event: "view_item",
    ecommerce: {
      currency: "BDT",
      value: unitPrice,
      items: [
        {
          item_id: String(CONFIG.productId),
          item_name: CONFIG.productName,
          item_brand: CONFIG.productBrand,
          item_category: CONFIG.productCategory,
          price: unitPrice,
          quantity: 1
        }
      ]
    }
  });
}

// 2. Begin Checkout
function triggerBeginCheckout() {
  if (state.checkoutFired) return;
  state.checkoutFired = true;

  var subtotal = CONFIG.prices[state.qty] || (1249 + (state.qty - 3) * 416);
  var totalCartValue = parseFloat(Number(subtotal).toFixed(2));

  window.dataLayer = window.dataLayer || [];
  window.dataLayer.push({ ecommerce: null });
  window.dataLayer.push({
    event: "begin_checkout",
    ecommerce: {
      currency: "BDT",
      value: totalCartValue,
      items: [
        {
          item_id: String(CONFIG.productId),
          item_name: CONFIG.productName,
          item_brand: CONFIG.productBrand,
          item_category: CONFIG.productCategory,
          price: parseFloat(Number(subtotal / state.qty).toFixed(2)),
          quantity: state.qty
        }
      ]
    }
  });
}

// Phone helper: format to E.164 (+880...)
function formatPhoneNumberE164(phone) {
  if (!phone) return "";
  var cleaned = String(phone).replace(/[^\d+]/g, '');
  if (cleaned.indexOf('+880') === 0) {
    return cleaned;
  }
  if (cleaned.indexOf('880') === 0) {
    return '+' + cleaned;
  }
  if (cleaned.indexOf('0') === 0) {
    return '+88' + cleaned;
  }
  if (cleaned.length === 10 && cleaned.indexOf('1') === 0) {
    return '+880' + cleaned;
  }
  return cleaned.indexOf('+') === 0 ? cleaned : ('+880' + cleaned);
}

// 3. Purchase Event (Order Success)
function triggerPurchaseEvent(orderResult, submittedData) {
  if (state.purchaseFired) return;
  state.purchaseFired = true;

  var rawName = (submittedData.name || '').trim();
  var nameParts = rawName ? rawName.split(/\s+/) : [];
  var firstName = nameParts.length > 0 ? nameParts[0] : 'Customer';
  var lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : firstName;

  var formattedPhone = formatPhoneNumberE164(submittedData.phone || '');
  var emailAddress = (submittedData.email || '').toLowerCase().trim();

  var streetAddress = submittedData.address || '';
  var city = state.shippingType === 1 ? 'Dhaka' : 'Outside Dhaka';
  var region = state.shippingType === 1 ? 'Dhaka' : 'Bangladesh';

  var qty = parseInt(submittedData.quantity, 10) || state.qty || 1;
  var subtotal = CONFIG.prices[qty] || (1249 + (qty - 3) * 416);
  var shippingCost = parseFloat(Number(orderResult.shipping_charge !== undefined ? orderResult.shipping_charge : state.deliveryCharge).toFixed(2));
  var totalOrderValue = parseFloat(Number(orderResult.grand_total !== undefined ? orderResult.grand_total : (subtotal + shippingCost)).toFixed(2));
  var transactionId = String(orderResult.invoice_no || orderResult.order_id || 'ORD-' + Date.now());

  window.dataLayer = window.dataLayer || [];
  window.dataLayer.push({ ecommerce: null });
  window.dataLayer.push({
    event: "purchase",
    user_data: {
      email_address: emailAddress,
      phone_number: formattedPhone,
      address: {
        first_name: firstName,
        last_name: lastName,
        street: streetAddress,
        city: city,
        region: region,
        postal_code: "",
        country: "BD"
      }
    },
    ecommerce: {
      transaction_id: transactionId,
      value: totalOrderValue,
      tax: 0.00,
      shipping: shippingCost,
      currency: "BDT",
      coupon: "",
      items: [
        {
          item_id: String(CONFIG.productId),
          item_name: CONFIG.productName,
          item_brand: CONFIG.productBrand,
          item_category: CONFIG.productCategory,
          price: parseFloat(Number(subtotal / qty).toFixed(2)),
          quantity: qty
        }
      ]
    }
  });

  console.log('[GTM Tracking] Purchase Event Pushed:', {
    transaction_id: transactionId,
    value: totalOrderValue,
    phone: formattedPhone
  });
}

/* ========================================
   UI INTERACTION & QUANTITY MANAGEMENT
   ======================================== */

/* Select package from pricing cards or form buttons */
function selectPackage(qty) {
  state.qty = Math.max(1, parseInt(qty));

  // Sync Pricing cards
  document.querySelectorAll('.price-card').forEach(function(c) {
    c.classList.toggle('selected', parseInt(c.dataset.qty) === state.qty);
  });

  // Sync Form package buttons
  document.querySelectorAll('.form-pkg-btn').forEach(function(b) {
    b.classList.toggle('active', parseInt(b.dataset.qty) === state.qty);
  });

  // Sync Stepper
  var qtyDisplay = document.getElementById('qtyDisplay');
  if (qtyDisplay) qtyDisplay.textContent = state.qty;

  updateSummary();
  updateSticky();
}

/* Step quantity in form (+ or -) */
function stepQty(delta) {
  var newQty = state.qty + delta;
  if (newQty < 1) newQty = 1;
  selectPackage(newQty);
  triggerBeginCheckout();
}

/* Select shipping type (Inside/Outside Dhaka) */
function selectShippingType(type, charge, isUserAction) {
  if (isUserAction === undefined) isUserAction = true;
  state.shippingType = parseInt(type);
  state.deliveryCharge = parseFloat(charge);

  var dhakaBtn = document.getElementById('shipDhakaBtn');
  var outsideBtn = document.getElementById('shipOutsideBtn');

  if (state.shippingType === 1) {
    if (dhakaBtn) dhakaBtn.classList.add('active');
    if (outsideBtn) outsideBtn.classList.remove('active');
  } else {
    if (outsideBtn) outsideBtn.classList.add('active');
    if (dhakaBtn) dhakaBtn.classList.remove('active');
  }

  updateSummary();
  if (isUserAction) {
    triggerBeginCheckout();
  }
}

/* Color selection — page */
function selectColor(el) {
  document.querySelectorAll('.color-btn').forEach(function(b) { b.classList.remove('active'); });
  el.classList.add('active');
  state.color = el.dataset.color;
  document.querySelectorAll('.form-color-btn').forEach(function(b) {
    b.classList.toggle('active', b.dataset.color === state.color);
  });
}

/* Color selection — form */
function selectFormColor(el) {
  document.querySelectorAll('.form-color-btn').forEach(function(b) { b.classList.remove('active'); });
  el.classList.add('active');
  state.color = el.dataset.color;
  document.querySelectorAll('.color-btn').forEach(function(b) {
    b.classList.toggle('active', b.dataset.color === state.color);
  });
  triggerBeginCheckout();
}

/* Update order summary */
function updateSummary() {
  var qty = state.qty;
  var subtotal = CONFIG.prices[qty] || (1249 + (qty - 3) * 416);
  var delivery = state.deliveryCharge;
  var qtyLabels = { 1: '১টা', 2: '২টা', 3: '৩টা' };

  var summaryProduct = document.getElementById('summaryProduct');
  if (summaryProduct) summaryProduct.textContent = (qtyLabels[qty] || (qty + 'টা')) + ' Turbo Fan';

  var summarySubtotal = document.getElementById('summarySubtotal');
  if (summarySubtotal) summarySubtotal.textContent = '৳' + fmt(subtotal);

  var summaryDelivery = document.getElementById('summaryDelivery');
  if (summaryDelivery) summaryDelivery.textContent = '৳' + fmt(delivery);

  var total = subtotal + delivery;
  var summaryTotal = document.getElementById('summaryTotal');
  if (summaryTotal) summaryTotal.textContent = '৳' + fmt(total);

  // Show savings
  var saveEl = document.getElementById('summarySave');
  if (saveEl) {
    var fullPrice = 649 * qty;
    var saved = fullPrice - subtotal;
    if (saved > 0) {
      saveEl.textContent = '🎉 আপনি সাশ্রয় করছেন ৳' + fmt(saved) + '!';
      saveEl.style.display = 'block';
    } else {
      saveEl.style.display = 'none';
    }
  }
}

/* Update sticky bar */
function updateSticky() {
  var qtyLabels = { 1: '১টা', 2: '২টা', 3: '৩টা' };
  var stickyQty = document.getElementById('stickyQty');
  var stickyPrice = document.getElementById('stickyPrice');
  var price = CONFIG.prices[state.qty] || (1249 + (state.qty - 3) * 416);

  if (stickyQty) stickyQty.textContent = (qtyLabels[state.qty] || (state.qty + 'টা')) + ' Turbo Fan';
  if (stickyPrice) stickyPrice.textContent = '৳' + fmt(price);
}

/* FAQ toggle */
function toggleFaq(el) {
  el.parentElement.classList.toggle('open');
}

/* Form validation */
function validateForm() {
  var valid = true;
  var name = document.getElementById('custName');
  var phone = document.getElementById('custPhone');
  var addr = document.getElementById('custAddress');

  [name, phone, addr].forEach(function(el) {
    if (el) el.classList.remove('error');
  });

  if (!name.value.trim()) {
    name.classList.add('error');
    valid = false;
  }
  if (!/^01[3-9]\d{8}$/.test(phone.value.trim().replace(/^\+88/, ''))) {
    phone.classList.add('error');
    valid = false;
  }
  if (!addr.value.trim()) {
    addr.classList.add('error');
    valid = false;
  }

  if (!valid) {
    var firstErr = document.querySelector('.form-input.error, .form-select.error');
    if (firstErr) {
      firstErr.focus();
      firstErr.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }

  return valid;
}

/* Submit order */
function submitOrder() {
  if (state.isSubmitting || state.submitted) return;

  if (!validateForm()) return;

  state.isSubmitting = true;
  var btn = document.getElementById('submitBtn');
  btn.disabled = true;
  var originalBtnText = btn.textContent;
  btn.textContent = 'অর্ডার প্রসেস হচ্ছে...';

  var qty = state.qty;
  var subtotal = CONFIG.prices[qty] || (1249 + (qty - 3) * 416);
  var delivery = state.deliveryCharge;
  var total = subtotal + delivery;

  var custName = document.getElementById('custName').value.trim();
  var custPhone = document.getElementById('custPhone').value.trim();
  var custAddress = document.getElementById('custAddress').value.trim();
  var custNote = document.getElementById('custNote').value.trim();

  var orderPayload = {
    product_id: CONFIG.productId,
    name: custName,
    phone: custPhone,
    address: custAddress,
    shipping_type: state.shippingType,
    quantity: qty,
    color: state.color,
    note: custNote
  };

  fetch(CONFIG.orderApi, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-TOKEN': CONFIG.csrfToken || document.querySelector('meta[name="csrf-token"]').getAttribute('content'),
      'Accept': 'application/json',
      'X-Requested-With': 'XMLHttpRequest'
    },
    body: JSON.stringify(orderPayload)
  })
  .then(function(res) {
    return res.json().then(function(data) {
      if (!res.ok) {
        throw new Error(data.message || 'অর্ডার করতে সমস্যা হয়েছে। অনুগ্রহ করে আবার চেষ্টা করুন।');
      }
      return data;
    });
  })
  .then(function(res) {
    if (res.success) {
      state.submitted = true;
      // Trigger Purchase DataLayer & Pixel Event
      triggerPurchaseEvent(res, orderPayload);

      // Update success box details
      var successCustName = document.getElementById('successCustName');
      if (successCustName) successCustName.textContent = custName;

      var successInvoice = document.getElementById('successInvoice');
      if (successInvoice) successInvoice.textContent = res.invoice_no || 'Pending';

      var successGrandTotal = document.getElementById('successGrandTotal');
      if (successGrandTotal) successGrandTotal.textContent = '৳' + fmt(res.grand_total || total);

      document.getElementById('orderFormWrap').style.display = 'none';
      var successEl = document.getElementById('orderSuccess');
      successEl.classList.add('show');
      successEl.style.display = 'block';
      successEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
    } else {
      alert(res.message || 'অর্ডার প্রক্রিয়া করা যায়নি।');
      state.isSubmitting = false;
      btn.disabled = false;
      btn.textContent = originalBtnText;
    }
  })
  .catch(function(err) {
    console.error('Order error:', err);
    alert(err.message || 'একটি ত্রুটি ঘটেছে। আপনার ইন্টারনেট সংযোগ পরীক্ষা করুন অথবা কল করে অর্ডার করুন।');
    state.isSubmitting = false;
    btn.disabled = false;
    btn.textContent = originalBtnText;
  });
}

/* Sticky bar visibility */
var heroEl = document.querySelector('.hero');
var stickyBar = document.getElementById('stickyBar');
var orderSection = document.getElementById('order-form');

function checkSticky() {
  if (!heroEl || !stickyBar || !orderSection) return;
  var heroBottom = heroEl.getBoundingClientRect().bottom;
  var orderTop = orderSection.getBoundingClientRect().top;
  var show = heroBottom < 0 && orderTop > window.innerHeight;
  stickyBar.classList.toggle('visible', show);
}

window.addEventListener('scroll', checkSticky, { passive: true });

/* Init defaults on load */
document.addEventListener('DOMContentLoaded', function() {
  selectPackage(3);
  selectShippingType(1, {{ isset($shipping_inside->shipping_charge) ? (int)$shipping_inside->shipping_charge : 70 }}, false);
  triggerViewItem();
});
</script>

</body>
